/**
 * A declared definition against a baseline: the three-way compare. Emits the
 * converging update row (config-moved fields) plus blocking-drift rows
 * (remote-moved fields). A declared-but-absent-from-baseline definition is
 * ambiguous and blocks as a whole.
 */
function diffEntityTypeWithBaseline(
  desired: DesiredEntityType,
  remote: RemoteEntityType | undefined,
  baseline: Baseline | undefined,
  prune: boolean
): { row: EntityTypeDiffRow; blocking: BlockingDriftRow[] } {
  if (!remote) {
    return { row: diffEntityType(desired, remote, prune), blocking: [] };
  }
  if (!baseline) {
    return { row: diffEntityType(desired, remote, prune), blocking: [] };
  }
  const attr = baseline.attribution.entityTypes.find(
    (a) => a.slug === desired.slug
  );
  if (!attr) {
    // No baseline entry — ambiguous only when there's an actual mismatch. A
    // definition already in sync (desired == remote) is a noop, so existing
    // orgs can establish their first baseline without blocking.
    // Inherit unmanaged omitted facets from remote (name/description/UI
    // properties) so a server-defaulted name does not false-block.
    const inSync = deepEqual(
      projectEntityForSync({
        name: desired.name ?? remote.name,
        description: desired.description ?? remote.description,
        required: desired.required,
        properties: {
          ...Object.fromEntries(
            Object.entries(remote.properties ?? {}).filter(
              ([k]) => !(k in (desired.properties ?? {}))
            )
          ),
          ...(desired.properties ?? {}),
        },
        backing: desired.backing ?? remote.backing,
        metrics: desired.metrics ?? remote.metrics,
        eventKinds: desired.eventKinds ?? remote.eventKinds,
        viewTemplate: desired.viewTemplate ?? remote.viewTemplate,
        resolutionPolicy: desired.resolutionPolicy,
        schemaExtras: remote.schemaExtras,
      }),
      projectEntityForSync(remote)
    );
    if (inSync) {
      return {
        row: {
          kind: "entity-type",
          verb: "noop",
          id: desired.slug,
          desired,
          remote,
        },
        blocking: [],
      };
    }
    return {
      row: {
        kind: "entity-type",
        verb: "noop",
        id: desired.slug,
        desired,
        remote,
      },
      blocking: [
        {
          kind: "entity-type",
          verb: "drift",
          blocking: true,
          id: desired.slug,
          // Field-qualified so blocked candidates use action=revert, not delete.
          field: "definition",
        },
      ],
    };
  }
  const threeWay = compareEntityTypeThreeWay(desired, remote, attr, prune);
  return {
    row: {
      kind: "entity-type",
      verb: threeWay.changedFields.length > 0 ? "update" : "noop",
      id: desired.slug,
      desired,
      remote,
      ...(threeWay.changedFields.length > 0
        ? { changedFields: threeWay.changedFields }
        : {}),
    },
    blocking: threeWay.blockingFields.map((b) => ({
      kind: "entity-type",
      verb: "drift",
      blocking: true,
      id: desired.slug,
      field: b.field,
      remoteChange: b.remoteChange,
    })),
  };
}

