            const a = baseline?.attribution.watchers.find(
              (x) => x.slug === slug
            );
            return (
              !!a &&
              deepEqual(
                projectRemoteWatcher(remoteWatcher),
                projectRemoteWatcher(a)
              )
            );
          }
        )
      );
    }
  }
}

