1	/**
2	 * Deployment identity for `lobu apply`.
3	 *
4	 * Each apply run mints an `apply_id`, sends it as `x-lobu-apply-id` on every
5	 * mutation (the server stamps its config-audit events with it), and posts a
6	 * summary to `POST /api/<org>/deployments` at the end — including the
7	 * redacted desired-state snapshot (`manifest`) that makes the deployment
8	 * self-contained: `lobu rollback <apply_id>` re-applies it through the same
9	 * diff/execute engine, repointing connectors to their retained versions. The
10	 * summary still records the config repo's HEAD SHA so git-first rollback
11	 * (revert commit → re-apply) stays first-class for config-as-code orgs.
12	 */
13	
14	import { execFileSync } from "node:child_process";
15	import { createHash, randomUUID } from "node:crypto";
16	import { deepRedactSecrets, REDACTED_SENTINEL } from "@lobu/core";
17	import type { DesiredState } from "./desired-state.js";
18	import type { DiffPlan, DiffRow, RemoteSnapshot } from "./diff.js";
19	import {
20	  canonical,
21	  effectiveEntityTypeAfterApply,
22	  effectiveRelationshipTypeAfterApply,
23	  projectDesiredWatcher,
24	} from "./diff.js";
25	
26	export function mintApplyId(): string {
27	  return `apl_${randomUUID()}`;
28	}
29	
30	export interface GitInfo {
31	  sha: string | null;
32	  dirty: boolean | null;
33	}
34	
35	/** HEAD SHA + dirty flag of the config repo; nulls outside a git work tree. */
36	export function collectGitInfo(cwd: string): GitInfo {
37	  try {
38	    const sha = execFileSync("git", ["rev-parse", "HEAD"], {
39	      cwd,
40	      stdio: ["ignore", "pipe", "ignore"],
41	    })
42	      .toString()
43	      .trim();
44	    const porcelain = execFileSync("git", ["status", "--porcelain"], {
45	      cwd,
46	      stdio: ["ignore", "pipe", "ignore"],
47	    })
48	      .toString()
49	      .trim();
50	    return { sha: sha || null, dirty: porcelain.length > 0 };
51	  } catch {
52	    return { sha: null, dirty: null };
53	  }
54	}
55	
56	/**
57	 * Structurally redact the fields that hold RESOLVED secret values in process
58	 * memory — agent `providerKeys[].value`, org provider `apiKey`, and auth-profile
59	 * `credentials` (resolved from `$VAR`/`secret()` at map time) — then deep-redact
60	 * by key-name denylist. Shared by the manifest hash and the stored deployment
61	 * snapshot: a snapshot NEVER carries a secret value, so `lobu rollback`
62	 * structurally cannot re-apply one.
63	 */
64	export function redactDesiredState(
65	  state: DesiredState
66	): Record<string, unknown> {
67	  return deepRedactSecrets({
68	    ...state,
69	    agents: state.agents.map((agent) => ({
70	      ...agent,
71	      providerKeys: agent.providerKeys.map((k) => ({
72	        providerId: k.providerId,
73	        value: REDACTED_SENTINEL,
74	      })),
75	    })),
76	    providers: (state.providers ?? []).map((p) => ({
77	      ...p,
78	      apiKey: REDACTED_SENTINEL,
79	    })),
80	    connectors: {
81	      ...state.connectors,
82	      authProfiles: state.connectors.authProfiles.map((profile) => ({
83	        ...(profile as unknown as Record<string, unknown>),
84	        credentials: REDACTED_SENTINEL,
85	      })),
86	    },
87	  }) as Record<string, unknown>;
88	}
89	
90	/**
91	 * sha256 of the redacted, canonicalized desired state. The hash identifies a
92	 * config revision; two applies of the same config (same secrets or not) hash
93	 * identically because secret VALUES never participate.
94	 */
95	export function computeManifestHash(state: DesiredState): string {
96	  return `sha256:${createHash("sha256")
97	    .update(canonical(redactDesiredState(state)))
98	    .digest("hex")}`;
99	}
100	
101	export const SNAPSHOT_VERSION = 1;
102	
103	export interface DeploymentManifest {
104	  version: typeof SNAPSHOT_VERSION;
105	  /**
106	   * The redacted desired state, minus connector source bytes: connector
107	   * definitions are stripped to declaration metadata, and the artifacts they
108	   * resolved to ride `connector_versions` below as retained
109	   * (org, key, version) pins — a deployment is self-contained without ever
110	   * embedding code or secrets.
111	   */
112	  state: Record<string, unknown>;
113	  /** Active connector version per declared key, recorded post-install. */
114	  connector_versions: Record<string, string>;
115	  /**
116	   * The attribution baseline for the three-way drift compare: the effective
117	   * entity/rel-type and Behavior state AFTER this apply (declared config
118	   * values + preserved unmanaged facets). Absent on legacy manifests — treated
119	   * as "no baseline" (block on remote mismatches, never auto-delete).
120	   */
121	  attribution?: {
122	    entityTypes: unknown[];
123	    relationshipTypes: unknown[];
124	    watchers: unknown[];
125	  };
