56	/**
57	 * Structurally redact the fields that hold RESOLVED secret values in process
58	 * memory — agent `providerKeys[].value`, org provider `apiKey`, and auth-profile
59	 * `credentials` (resolved from `$VAR`/`secret()` at map time) — then deep-redact
60	 * by key-name denylist. Shared by the manifest hash and the stored deployment
61	 * snapshot: a snapshot NEVER carries a secret value, so `lobu rollback`
62	 * structurally cannot re-apply one.
63	 */
64	export function redactDesiredState(
65	  state: DesiredState
66	): Record<string, unknown> {
67	  return deepRedactSecrets({
68	    ...state,
69	    agents: state.agents.map((agent) => ({
70	      ...agent,
71	      providerKeys: agent.providerKeys.map((k) => ({
72	        providerId: k.providerId,
73	        value: REDACTED_SENTINEL,
74	      })),
75	    })),
76	    providers: (state.providers ?? []).map((p) => ({
77	      ...p,
78	      apiKey: REDACTED_SENTINEL,
79	    })),
80	    connectors: {
81	      ...state.connectors,
82	      authProfiles: state.connectors.authProfiles.map((profile) => ({
83	        ...(profile as unknown as Record<string, unknown>),
84	        credentials: REDACTED_SENTINEL,
85	      })),
86	    },
87	  }) as Record<string, unknown>;
88	}
