90	/**
91	 * sha256 of the redacted, canonicalized desired state. The hash identifies a
92	 * config revision; two applies of the same config (same secrets or not) hash
93	 * identically because secret VALUES never participate.
94	 */
95	export function computeManifestHash(state: DesiredState): string {
96	  return `sha256:${createHash("sha256")
97	    .update(canonical(redactDesiredState(state)))
98	    .digest("hex")}`;
99	}
