// No baseline was ever recorded, so `owned` proves nothing — emptiness is
// absence of evidence, not evidence the config owns nothing. Prune-off keeps
// the pre-gate behavior (informational drift; nothing was going to be
// deleted anyway). Prune-on blocks rather than deleting: the config asked to
// delete un-declared definitions, but on a first apply we cannot tell an
// apply-created definition from a hand-made one, and deleting the wrong one
// is unrecoverable. Blocking resolves on the next apply, once this one
// records a baseline.
if (!baseline?.recorded) {
  return legacyDelete
    ? ({ kind, verb: "drift", blocking: true, id: remote.slug, remote } as DiffRow)
    : ({ kind, verb: "drift", id: remote.slug, remote } as DiffRow);
}

