// sits inside `if (prune && …)`), so this makes the three definition kinds
// agree with connectors rather than inventing a new rule.
describe("remote-only definitions are only blocking under prune", () => {
  const uiCreated = (): RemoteSnapshot["entityTypes"] =>
    [
      { id: 7, slug: "ui_made", name: "UI Made", organization_id: "org-1" },
    ] as RemoteSnapshot["entityTypes"];

  test("recorded baseline, prune off: an unowned UI-created type is informational drift", () => {
    const remote = emptyRemote();
    remote.entityTypes = [remoteTask(1), ...uiCreated()];
    const plan = computeDiff(buildState([taskType()]), remote, {
      orgId: "org-1",
      prune: false,
      baseline: baselineFor([attributedTask(1)], [1]),
    });
    const row = plan.rows.find((r) => r.id === "ui_made");
    expect(row?.verb).toBe("drift");
    expect((row as { blocking?: boolean }).blocking).toBeUndefined();
  });

  test("recorded baseline, prune off: the rest of the plan still executes", () => {
    const remote = emptyRemote();
    remote.entityTypes = [remoteTask(1, { name: "Task" }), ...uiCreated()];
    const plan = computeDiff(
      buildState([taskType({ name: "Task Renamed" })]),
      remote,
      {
        orgId: "org-1",
        prune: false,
        baseline: baselineFor([attributedTask(1)], [1]),
      }
    );
    expect(plan.rows.find((r) => r.id === "task")?.verb).toBe("update");
    expect(
      plan.rows.filter(
        (r) => r.verb === "drift" && (r as { blocking?: boolean }).blocking
      )
    ).toEqual([]);
  });

  test("recorded baseline, prune ON: an unowned UI-created type still blocks and is never deleted", () => {
    const remote = emptyRemote();
    remote.entityTypes = [remoteTask(1), ...uiCreated()];
    const plan = computeDiff(buildState([taskType()]), remote, {
      orgId: "org-1",
      prune: true,
      baseline: baselineFor([attributedTask(1)], [1]),
    });
    const row = plan.rows.find((r) => r.id === "ui_made");
    expect(row?.verb).toBe("drift");
    expect((row as { blocking?: boolean }).blocking).toBe(true);
    expect(plan.rows.some((r) => r.verb === "delete")).toBe(false);
  });

  test("recorded baseline, prune ON: an owned+unchanged type is still delete-eligible", () => {
    const remote = emptyRemote();
    remote.entityTypes = [remoteTask(1)];
    const plan = computeDiff(buildState([]), remote, {
      orgId: "org-1",
      prune: true,
      baseline: baselineFor([attributedTask(1)], [1]),
    });
    expect(plan.rows.find((r) => r.id === "task")?.verb).toBe("delete");
  });
});
