        );
      }
      break;
    case "noop":
      lines.push(`  ${prefix} ${label} ${id}`);
      if (row.kind === "auth-profile" && row.needsAuth) {
        lines.push(
          `      ${chalk.yellow("⚠")} interactive auth still pending — complete it via the connect URL printed after apply`
        );
      }
      break;
