  const deletePart = del > 0 ? `, ${chalk.red(`${del} delete`)}` : "";
  return chalk.bold(
    `Summary: ${chalk.green(`${create} create`)}, ${chalk.yellow(`${update} update`)}, ${chalk.dim(`${noop} noop`)}, ${chalk.cyan(`${drift} drift`)}${deletePart}`
  );
}

