1	import chalk from "chalk";
2	import type { DiffPlan, DiffRow } from "./diff.js";
3	
4	const VERB_PREFIX = {
5	  create: chalk.green("+"),
6	  update: chalk.yellow("~"),
7	  noop: chalk.dim("="),
8	  drift: chalk.cyan("?"),
9	  delete: chalk.red("-"),
10	} as const;
11	
12	const KIND_LABEL: Record<DiffRow["kind"], string> = {
13	  agent: "agent",
14	  settings: "settings",
15	  "entity-type": "entity-type",
16	  "relationship-type": "relationship-type",
17	  watcher: "behavior",
18	  "connector-definition": "connector-definition",
19	  "auth-profile": "auth-profile",
20	  connection: "connection",
21	  feed: "feed",
22	  "inference-provider": "provider",
23	};
24	
25	const KIND_HEADING: Record<DiffRow["kind"], string> = {
26	  agent: "agents",
27	  settings: "settings",
28	  "entity-type": "entity-types",
29	  "relationship-type": "relationship-types",
30	  watcher: "behaviors",
31	  "connector-definition": "connector-definitions",
32	  "auth-profile": "auth-profiles",
33	  connection: "connections",
34	  feed: "feeds",
35	  "inference-provider": "providers",
36	};
37	
38	function fieldsList(fields: string[] | undefined): string {
39	  if (!fields?.length) return "";
40	  return chalk.dim(` (${fields.join(", ")})`);
41	}
42	
43	/**
44	 * One-line preview of a value for the plan. Objects and arrays are the common
45	 * case (a property schema, an eventKinds list), so they are compacted rather
46	 * than pretty-printed — the plan is a scannable summary, and an operator who
47	 * needs the full body has the config and the dashboard.
48	 */
49	const VALUE_PREVIEW_MAX = 72;
50	function valuePreview(value: unknown): string {
51	  if (value === undefined) return chalk.dim("(unset)");
52	  let text: string;
53	  try {
54	    text = JSON.stringify(value) ?? String(value);
55	  } catch {
56	    // Cyclic or otherwise unserializable — never let the plan throw.
57	    text = String(value);
58	  }
59	  return text.length > VALUE_PREVIEW_MAX
60	    ? `${text.slice(0, VALUE_PREVIEW_MAX - 1)}…`
61	    : text;
62	}
63	
64	/**
65	 * `field: <remote> → <config>` lines under an update row, so the operator can
66	 * see what the apply overwrites instead of only which field names move. Absent
67	 * on rows from the two-way paths, which never computed the pair.
68	 */
69	function changedValueLines(
70	  changed: Array<{ field: string; from: unknown; to: unknown }> | undefined
71	): string[] {
72	  if (!changed?.length) return [];
73	  return changed.map(
74	    (c) =>
75	      `      ${chalk.cyan(c.field)}: ${chalk.dim(valuePreview(c.from))} → ${valuePreview(c.to)}`
76	  );
77	}
78	
79	function rowId(row: DiffRow): string {
80	  if (
81	    row.kind === "connector-definition" &&
82	    row.desired?.key &&
83	    row.desired.sourcePath
84	  ) {
85	    return `${row.desired.key} (from ${row.desired.sourceFile})`;
86	  }
87	  if (row.kind === "connector-definition" && row.desired) {
88	    return row.desired.sourceUrl
89	      ? `${row.desired.sourceFile} (${row.desired.sourceUrl})`
90	      : row.desired.sourceFile;
91	  }
92	  return row.id;
93	}
94	
95	function renderRow(row: DiffRow): string[] {
96	  const prefix = VERB_PREFIX[row.verb];
97	  const label = chalk.bold(KIND_LABEL[row.kind]);
98	  const id = rowId(row);
99	  const lines: string[] = [];
100	
101	  switch (row.verb) {
102	    case "create":
103	      lines.push(`  ${prefix} ${label} ${id}`);
104	      if (
105	        row.kind === "connector-definition" &&
106	        row.installedRemotely &&
107	        row.desired?.key
108	      ) {
109	        lines.push(
110	          `      ${chalk.dim("(already installed — apply re-pushes source; no-op if unchanged)")}`
111	        );
112	      }
113	      if (row.kind === "auth-profile" && row.needsAuth) {
114	        lines.push(
115	          `      ${chalk.yellow("⚠")} interactive auth — complete it via the connect URL printed after apply`
116	        );
117	      }
118	      break;
119	    case "update": {
120	      const changedValues =
121	        "changedValues" in row ? row.changedValues : undefined;
122	      const previewedFields = new Set(
123	        changedValues?.map((change) => change.field) ?? []
124	      );
125	      const unpreviewedFields =
126	        "changedFields" in row
127	          ? row.changedFields?.filter((field) => !previewedFields.has(field))
128	          : undefined;
129	      lines.push(
130	        `  ${prefix} ${label} ${id}${fieldsList(unpreviewedFields)}`
131	      );
132	      lines.push(...changedValueLines(changedValues));
133	      if (row.kind === "auth-profile" && row.needsAuth) {
134	        lines.push(
135	          `      ${chalk.yellow("⚠")} interactive auth — complete it via the connect URL printed after apply`
136	        );
137	      }
138	      break;
139	    }
140	    case "noop":
141	      lines.push(`  ${prefix} ${label} ${id}`);
142	      if (row.kind === "auth-profile" && row.needsAuth) {
143	        lines.push(
144	          `      ${chalk.yellow("⚠")} interactive auth still pending — complete it via the connect URL printed after apply`
145	        );
146	      }
147	      break;
148	    case "drift":
149	      lines.push(
150	        "blocking" in row && row.blocking
151	          ? `  ${prefix} ${label} ${id} ${chalk.red("(remote change not in config — blocks this apply)")}`
152	          : `  ${prefix} ${label} ${id} ${chalk.cyan("(drift — ignored, not deleted)")}`
153	      );
154	      break;
155	    case "delete":
156	      lines.push(
157	        `  ${prefix} ${label} ${id} ${chalk.red("(removed from config — will be deleted)")}`
158	      );
159	      break;
160	  }
161	
162	  return lines;
163	}
