366	export async function cleanupTestDatabase(): Promise<void> {
367	  // All three clearers live in dedicated leaf modules so this path never
368	  // statically (or dynamically) loads `test-helpers`, `mcp-handler`, or
369	  // `workspace/multi-tenant` — those files transitively pull in
370	  // `@lobu/connector-sdk` via the full app graph, which breaks gateway-only
371	  // `bun:test` runs that don't have the workspace `dist/` built. The cache
372	  // *instances* are still the same singletons read/written by production
373	  // code; only the test clearer is exported from a leaf.
374	  clearMcpSessions();
375	  clearInMemoryMcpSessionsForTests();
376	  // Multi-tenant auth TTL caches (orgSlug/memberRole/owner/session) survive across
377	  // requests by design. Without this, a test that recreates the org with the same slug
378	  // but a different UUID gets a 403 because requests still see the stale orgId.
379	  clearMultiTenantCachesForTests();
380	
381	  const db = getTestDb();
382	
383	  // Get all tables in public schema
384	  const tables = await db`
385	    SELECT tablename FROM pg_tables
386	    WHERE schemaname = 'public'
387	    AND tablename NOT LIKE 'pg_%'
388	    AND tablename NOT LIKE 'schema_migrations%'
389	  `;
390	
391	  if (tables.length > 0) {
392	    const quotedTables = tables.map(({ tablename }) => `"${tablename}"`).join(', ');
393	    // Truncate every table, retrying on deadlock. See `truncateAllTables` for
394	    // why the trigger-disable runs via `SET LOCAL` inside a transaction (#1607)
395	    // and why a co-running background poller's DML can deadlock the cleanup.
396	    const canDisableTriggers = await connectionCanDisableTriggers(db);
397	    await truncateAllTables(db, quotedTables, canDisableTriggers);
398	  }
399	
400	  // Fix check constraints that are out-of-date relative to the app code
401	  await fixSchemaConstraints(db);
402	}
