test("a whole-definition block names what the definition IS, not just its slug", () => {
  // A slug alone ("chat-slack-97") cannot tell an operator whether to adopt
  // the definition or delete it. The block carries an allowlisted identity
  // projection so the report can answer that without a dashboard trip.
  const desired = buildState([]);
  const remote = emptyRemote();
  remote.entityTypes = [
    remoteTask(9, {
      slug: "ui_made",
      name: "UI Made",
      description: "Created from the dashboard",
    }),
  ];
  const baseline = baselineFor([], []);

  const plan = computeDiff(desired, remote, {
    orgId: "org-1",
    baseline,
    prune: true,
  });
  const row = plan.rows.find((r) => r.id === "ui_made") as {
    blocking?: boolean;
    remoteChange?: unknown;
  };
  expect(row.blocking).toBe(true);
  expect(row.remoteChange).toEqual({
    name: "UI Made",
    description: "Created from the dashboard",
  });
});

test("the identity projection carries only name and description", () => {
  // It is rendered verbatim in the blocked report, so it must never widen
  // into the full remote row — that is how a secret reaches a terminal.
  const desired = buildState([]);
  const remote = emptyRemote();
  remote.entityTypes = [
    remoteTask(9, {
      slug: "ui_made",
      name: "UI Made",
      description: "d",
      properties: { token: { type: "string", default: "sk-live-secret" } },
    }),
  ];

  const plan = computeDiff(desired, remote, {
    orgId: "org-1",
    baseline: baselineFor([], []),
    prune: true,
  });
  const row = plan.rows.find((r) => r.id === "ui_made") as {
    remoteChange?: Record<string, unknown>;
  };
  expect(Object.keys(row.remoteChange ?? {}).sort()).toEqual([
    "description",
    "name",
  ]);
  expect(JSON.stringify(row.remoteChange)).not.toContain("sk-live-secret");
});

