/**
 * The identity of a remote-only definition, for the blocked report.
 *
 * A slug alone cannot tell an operator whether to adopt a definition or delete
 * it — `chat-slack-97` is unreadable, `"Messages in slack:D095U1QV667"` is not.
 * Callers build this explicitly rather than the helper reading it off `remote`,
 * so the allowlist is visible at every site: this object is printed verbatim,
 * and widening it to the whole remote row is how a stored secret reaches a
 * terminal. Name and description are the only fields any of the three kinds
 * needs, and neither is ever secret-bearing.
 */
export interface RemoteDefinitionIdentity {
  name?: string | null;
  description?: string | null;
}

