test("investmentRefsFromSnapshots records exactly what was emitted", () => {
  const [snapshot] = parseInvestmentDomSnapshot(
    INVESTMENT_RESPONSES,
    INVESTMENT_DOM_ACCOUNTS
  );
  const occurredAt = new Date("2026-08-12T17:25:00.000Z");
  const events = investmentSnapshotsToEvents([snapshot], occurredAt);
  const refs = investmentRefsFromSnapshots([snapshot]);

  // The checkpoint must round-trip: feeding this sync's refs back in on an
  // identical next sync closes nothing.
  expect(refs.map((r) => r.origin_id).sort()).toEqual(
    events.map((e) => e.origin_id).sort()
  );
  const next = investmentSnapshotsToEvents([snapshot], occurredAt, refs);
  expect(next.some((e) => e.metadata?.closed === true)).toBe(false);
});

