 * sold holding from an unchanged one.
 *
 * The origin id is stored rather than recomputed because `portfolio_id` and
 * `ref` both contain `-`, so a position origin id cannot be parsed back into
 * its parts unambiguously.
 */
export interface RevolutInvestmentRef {
  origin_id: string;
  portfolio_id: string;
  account_type: string;
  /** Present for positions, absent for a portfolio balance. */
  ref?: string;
  ticker?: string;
}

const portfolioOriginId = (portfolioId: string) =>
  `revolut-investment-portfolio-${portfolioId}`;
const positionOriginId = (portfolioId: string, ref: string) =>
  `revolut-investment-position-${portfolioId}-${ref}`;

/** The refs a sync emitted — store this as the investment checkpoint. */
export function investmentRefsFromSnapshots(
  snapshots: RevolutInvestmentSnapshot[]
): RevolutInvestmentRef[] {
  const refs: RevolutInvestmentRef[] = [];
  for (const snapshot of snapshots) {
    refs.push({
      origin_id: portfolioOriginId(snapshot.portfolioId),
      portfolio_id: snapshot.portfolioId,
      account_type: snapshot.accountType,
    });
    for (const position of snapshot.positions) {
      refs.push({
        origin_id: positionOriginId(snapshot.portfolioId, position.ref),
