1	/**
2	 * Midas connector — extension dispatcher wiring + dashboard DOM text parsing.
3	 *
4	 * Guards:
5	 *  - prod chrome_dispatcher injection (not ctx.channel)
6	 *  - Atlas TR "Pozisyonlar" table layout (live capture fixture)
7	 *  - European number format for both USD and TRY on the TR UI
8	 */
9	
10	import { readFileSync } from "node:fs";
11	import path from "node:path";
12	import { beforeAll, describe, expect, mock, test } from "bun:test";
13	import type { ChromeActionDispatcher } from "@lobu/connector-sdk";
14	import type { MidasCheckpoint } from "../midas.connector";
15	import { connectorSdkMock } from "./connector-sdk.mock";
16	
17	// Stub @lobu/connector-sdk (it pulls in playwright) so the connector imports
18	// without the browser stack. Shared superset — see connector-sdk.mock.ts.
19	mock.module("@lobu/connector-sdk", connectorSdkMock);
20	
21	let MidasConnector: typeof import("../midas.connector").default;
22	let requireExtensionDispatcher: typeof import("../midas.connector").requireExtensionDispatcher;
