56	  return new MidasConnector().sync({
57	    feedKey: "assets",
58	    config: {},
59	    checkpoint,
60	    sessionState: { chrome_dispatcher: dispatcherFor(bodyText) },
61	  } as never);
62	}
63	
64	// Synthetic Atlas TR "Pozisyonlar" capture — layout mirrors production, values
65	// are fabricated (no real holdings/quantities/prices) to avoid committing PII.
66	const DASHBOARD_FIXTURE = readFileSync(
