89	  "10",
90	  "$50,00",
91	  "$40,00",
92	  "$500,00",
93	  "%50,00",
94	  "$5,00(%1,00)",
95	  "$50,00(%12,50)",
96	  "n/a",
97	  "n/a",
98	  "n/a",
99	  "n/a",
100	  "n/a",
101	  "n/a",
